def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Label the exterior background using edge-connected 4-neighbors, then
    # inspect enclosed background components independently.
    exterior = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == background and (r, c) not in exterior:
                exterior.add((r, c))
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == background and (r, c) not in exterior:
                exterior.add((r, c))
                q.append((r, c))
    for_queue = ((1, 0), (-1, 0), (0, 1), (0, -1))
    while q:
        r, c = q.popleft()
        for dr, dc in for_queue:
            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and
                    grid[nr][nc] == background and (nr, nc) not in exterior):
                exterior.add((nr, nc))
                q.append((nr, nc))

    seen = set(exterior)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background or (r, c) in seen:
                continue
            component = set()
            q.append((r, c))
            seen.add((r, c))
            while q:
                cr, cc = q.popleft()
                component.add((cr, cc))
                for dr, dc in for_queue:
                    nr, nc = cr + dr, cc + dc
                    if (0 <= nr < h and 0 <= nc < w and
                            grid[nr][nc] == background and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        q.append((nr, nc))
            # The examples distinguish the small cavities from larger enclosed
            # regions: only cavities of up to six cells are recolored.
            if len(component) <= 6:
                for cr, cc in component:
                    out[cr][cc] = 4
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
